-- WDOS migration 003 · HQ inspiration messages (weekly, monthly) and pictures on announcements.
-- Headlines and key thoughts are the ones carried on the current WDOS artwork (weeks 1 to 13, months 1 to 60).
-- The body column is empty until the full Founder-approved texts are brought across.

CREATE TABLE IF NOT EXISTS hq_messages (
  id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  kind VARCHAR(12) NOT NULL,
  seq INT NOT NULL,
  network VARCHAR(8) NOT NULL DEFAULT 'ALL',
  theme VARCHAR(120) NOT NULL DEFAULT '',
  headline VARCHAR(190) NOT NULL,
  key_thought VARCHAR(400) NOT NULL DEFAULT '',
  body TEXT NULL,
  image VARCHAR(120) NOT NULL DEFAULT '',
  UNIQUE KEY uq_hq_messages (kind, seq, network)
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


ALTER TABLE announcements ADD COLUMN tone VARCHAR(16) NOT NULL DEFAULT '';


