INSERT INTO hq_messages (kind,seq,network,theme,headline,key_thought,image) VALUES
('weekly',1,'WGMN','','You are part of something bigger than yourself','Rooted women lead with purpose and strengthen others through their example.','hq-messages/wi001-wgmn.webp'),
('weekly',1,'WNNN','','You are the next generation of women leaders','You are not waiting to become a leader; you are learning to lead responsibly now.','hq-messages/wi001-wnnn.webp'),
('weekly',2,'WGMN','','Leadership begins with the heart','Care and accountability together create leadership people can trust.','hq-messages/wi002-wgmn.webp'),
('weekly',2,'WNNN','','Your purpose is bigger than your fear','Your voice grows stronger when it is guided by values and action.','hq-messages/wi002-wnnn.webp'),
('weekly',3,'WGMN','','Serving with purpose not pressure','Experience becomes valuable when it is used to lift another woman.','hq-messages/wi003-wgmn.webp'),
('weekly',3,'WNNN','','Leadership starts with knowing who you are','Confidence is built through responsibility, reflection and practice.','hq-messages/wi003-wnnn.webp'),
('weekly',4,'WGMN','','The power of showing up consistently','Healthy service protects both the mission and the woman who serves.','hq-messages/wi004-wgmn.webp'),
('weekly',4,'WNNN','','You do not have to be perfect to begin','You can ask for guidance and still be a strong young leader.','hq-messages/wi004-wnnn.webp'),
('weekly',5,'WGMN','','Women who lift other women build nations','What leaders practise consistently becomes the culture families and communities experience.','hq-messages/wi005-wgmn.webp'),
('weekly',5,'WNNN','','Young women with values can change communities','The habits you build today are shaping the influence you will carry tomorrow.','hq-messages/wi005-wnnn.webp'),
('weekly',6,'WGMN','','Your role is a trust','A dependable local action can strengthen the wider African network.','hq-messages/wi006-wgmn.webp'),
('weekly',6,'WNNN','','Your voice matters','Digital influence should always reflect dignity, safety and good judgement.','hq-messages/wi006-wnnn.webp'),
('weekly',7,'WGMN','','Identity gives leadership direction','Leadership is strongest when women leave other women stronger.','hq-messages/wi007-wgmn.webp'),
('weekly',7,'WNNN','','Confidence grows when you take responsibility','Your growth can open a path for another young woman.','hq-messages/wi007-wnnn.webp'),
('weekly',8,'WGMN','','Purpose makes service meaningful','Dignity must remain visible in every decision, message and follow-up.','hq-messages/wi008-wgmn.webp'),
('weekly',8,'WNNN','','Do not hide your light','Purpose becomes visible when you complete the next responsible step.','hq-messages/wi008-wnnn.webp'),
('weekly',9,'WGMN','','Values are your leadership compass','Rooted women lead with purpose and strengthen others through their example.','hq-messages/wi009-wgmn.webp'),
('weekly',9,'WNNN','','Purpose before pressure','You are not waiting to become a leader; you are learning to lead responsibly now.','hq-messages/wi009-wnnn.webp'),
('weekly',10,'WGMN','','Begin with what is in your hands','Care and accountability together create leadership people can trust.','hq-messages/wi010-wgmn.webp'),
('weekly',10,'WNNN','','Mentorship helps you see further','Your voice grows stronger when it is guided by values and action.','hq-messages/wi010-wnnn.webp'),
('weekly',11,'WGMN','','Your presence can create hope','Experience becomes valuable when it is used to lift another woman.','hq-messages/wi011-wgmn.webp'),
('weekly',11,'WNNN','','Discipline today builds influence tomorrow','Confidence is built through responsibility, reflection and practice.','hq-messages/wi011-wnnn.webp'),
('weekly',12,'WGMN','','Confidence grows through responsible action','Healthy service protects both the mission and the woman who serves.','hq-messages/wi012-wgmn.webp'),
('weekly',12,'WNNN','','You are becoming','You can ask for guidance and still be a strong young leader.','hq-messages/wi012-wnnn.webp'),
('weekly',13,'WGMN','','Foundation review and renewal','What leaders practise consistently becomes the culture families and communities experience.','hq-messages/wi013-wgmn.webp'),
